INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-033', 'SW', 'P1', 'OPEN', 'governance', NULL, 'TERM ADJUDICATION HAS NEVER RUN, AND NOTHING SAYS SO. Harvest at evidence, adjudicate at judgment (owner 2026-08-27, overruling DR-2026-08-24 section 2.4). The harvest half works -- derive it with: select count(*) from observed_terms. The adjudication half has produced nothing at all -- select count(*) from term_adjudications -- and db.py adjudicate-term exists, so this is a backlog, not a missing capability. CLAUDE.md section 6 says outright that zero links AFTER judgment is a defect, and no gap, no check and none of the five documents a cold-starting session reads names this. Found by walking the spine forward from this batch''s two admissions: research -> evidence walks, evidence -> judgment stops here with no marker. WHAT WOULD CLOSE IT: adjudicate the harvested terms, or record why the backlog is deliberate. WHAT WOULD MAKE IT VISIBLE MEANWHILE: a check asserting that observed_terms older than N batches have an adjudication, which is the general form of the same question.', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-034', 'SW', 'P2', 'OPEN', 'governance', NULL, 'AN EVIDENCE RETRIEVAL MADE THROUGH WebFetch LEAVES NO ARTEFACT, AND THE RECORD CANNOT TELL. CLAUDE.md section 5(c): verification must leave an artefact, and scripts/research/retrieval_log.py persists every payload before returning. WebFetch and WebSearch bypass it entirely. Measured on this batch: exec 72 records seven routes; ten attempts were made, three of them through WebFetch/WebSearch and therefore unpersisted -- and one of those three is the HTTP 503 that the session record then RETRACTED as never having happened, because the only evidence for it was the harness transcript. So an unpersisted retrieval produced a false claim, a false retraction of that claim, and no way to settle either without reading the transcript. WHAT WOULD FIX IT: retrieval_log.fetch as the only sanctioned route for evidence retrieval, with the tool-level alternatives named as forbidden in the research contract; or a check comparing a search_execution''s asserted route count against persisted artefacts, which needs an exec-to-artefact edge that does not exist.', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-035', 'SW', 'P3', 'OPEN', 'governance', NULL, 'THREE FIELDS THAT CAN ONLY BE RIGHT OR WRONG, NEVER INFORMATIVE (rule 8). (1) doctrine_sha in every attestation: the schema checks seven hex characters and nothing else, adherence_log_audit documents a Doctrine-SHA consistency check that is absent from its own CHECK_GROUPS, and the value means a different thing in each of its three homes -- a PR base commit, a merge commit, a file blob sha. Derive it from the doctrine file''s blob, as scripts/generate/context_map.py already does, and assert the derivation. (2) evidence_sources.metadata_quality: an argparse assertion with no CHECK and no derivation; the false-COMPLETE case is now caught by retrieval_log --verify-authors but the field is still typed rather than computed. (3) evidence_sources.jurisdiction: a judgement field that add-source accepts with no recorded warrant, while amend-source requires --reason for the same column. REF-01003 carries US with no persisted artefact supporting any jurisdiction -- its payload has empty affiliations for all five authors. ALSO: schemas/enums.py VerificationStatus admits OPEN and CLOSED, which are verification_DISPOSITION values, so the Pydantic mirror accepts a status the CLI refuses -- schema/SQLite drift is a bug, not a convention (CLAUDE.md section 7).', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-036', 'SW', 'P3', 'OPEN', 'governance', NULL, 'tools/pipeline_walk.py ATTRIBUTES ONLY CREATED ROWS, SO A BATCH THAT MINES LOOKS IDLE. It derives session columns through batch_capture_report._session_cols -- created_by_session, applied_by_session -- and never updated_by_session. This batch''s principal work was four backward mining passes, executed as UPDATEs to citation_mining rows earlier sessions created, so the walk shows only the two new deferral rows and a cold reader concludes the batch mined nothing: the inverse of the truth. Second defect in the same surface: data_migrations.applied_by_session holds the .md form of a session id by design (CLAUDE.md section 7), so each such session appears TWICE in the walk, once as itself and once as a .md twin that wrote only migration rows, inflating the session count. WHAT WOULD FIX IT: include updated_by_session in the attribution, labelled as an update rather than a create; and collapse the .md twin onto its bare stem.', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', '2026-09-18 22:45', 'session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining', NULL, NULL, NULL, NULL, NULL);
UPDATE "gaps" SET "description" = 'THE PROJECT RANKED ITS OWN MINING TARGETS AND GOT THEM EXACTLY BACKWARDS, TWICE, AND THE PREDICTOR THAT WOULD HAVE WORKED IS CHEAP. Batch 15 deferred three anchors with explicit rankings: REF-00984 (a systematic review of wheelchair SKILLS TESTS) HIGHEST-VALUE TARGET, REF-00985 (a biomechanics paper) LOWEST expected yield. Measured this batch against the same ramp/slope/gradient screen: REF-00984 yielded 0 of 38, REF-00985 yielded 23 of 46 and produced both of the batch anchoring-tier admissions. My own pre-registered priors were wrong in the same two places and in one further way -- I predicted REF-00984 would yield test-apparatus numbers needing a guard, and it yielded no slope references at all. THE REGULARITY IS DERIVABLE AND NEITHER SESSION DERIVED IT: a paper cites the literature of ITS OWN INDEPENDENT VARIABLE. REF-00985 measures propulsion effort, so it cites propulsion-on-slopes work; REF-00984 reviews measurement INSTRUMENTS, so it cites reliability, scoring and construct validity. Topical proximity of the ANCHOR to the slug predicted nothing; what the anchor MEASURES predicted everything. WHAT IS OWED: this is a hypothesis from two observations and must not become doctrine on that basis. Test it prospectively -- record a predicted yield for each deferred anchor BEFORE the pass, from what the anchor measures rather than what it is about, and check the prediction after. If it holds over a further three or four passes it belongs in the citation-miner skill relevance filter, which today screens DISCOVERIES for relevance and says nothing about ranking ANCHORS. A second, cheaper finding rides along and should be tested with it: 3 of the 3 best finds this batch (REF-01002 admitted, plus candidates 102 and 103) carry NO DOI in the deposit, so a DOI-keyed screen would have missed all three. || CORRECTED 2026-09-18: CLOSED ON A RETRACTED RESULT, AND THE RETRACTION WAS ALSO UNVALIDATED. See GAP-029. The founding observation here -- REF-00985 at 23 of 46 -- was never re-derived under the strict screen before the hypothesis was declared falsified. It has been now, and it is 8 of 46, the highest strict count of any anchor in the corpus. Re-run: python3 scripts/research/mining_screen.py --all --compare.', "updated_at" = '2026-09-18 22:44' WHERE "gap_id" = 'GAP-018';
UPDATE "gaps" SET "description" = 'GAP-016 IS NOT CLOSED: REF-01002 FULL TEXT IS UNOBTAINABLE BY EVERY ROUTE AVAILABLE TO THIS ENVIRONMENT, MEASURED ACROSS SEVEN. Batch 17 was convened to read it and could not. Routes, all persisted as artefacts: academia.edu 403 on two different copies, researchgate 403, JSTOR 200 whose body is a bot interstitial, SafetyLit 503 then empty, OpenAlex 429 with the environment budget exhausted. THE INFORMATIVE ONE IS CROSSREF: a bibliographic title search returns five neighbouring papers and not this one, which VERIFIES rather than assumes the no-DOI fact the whole problem rests on -- Journal of Architectural and Planning Research never deposited it. Consensus returned the record and the same abstract, corroborating existence at index level, not full text. WHAT THIS MEANS FOR THE DETERMINATION, UNCHANGED AND SAID AGAIN BECAUSE IT IS THE POINT: extraction 45 stays skim/preliminary, REF-01002 stays UNVERIFIED, gate 1 stays open, C10 keeps refusing the re-determination, parameter 3 x MOB stays undetermined. WHAT WOULD ACTUALLY WORK, and none of it is a search: a library or document-delivery route (JSTOR institutional access, ILL, or a request to the corresponding author, whose consultancy publishes its papers). THAT IS A DIFFERENT KIND OF WORK FROM A RETRIEVAL LADDER and the next batch should plan it as such rather than re-running the same seven routes and recording a second null. AN OPEN METADATA QUESTION RIDES ALONG: TRID prints the fourth author Weiner, Jerome M; a search summary rendered it Welner, J. M. Neither is a retrieved authoritative index. The stored author row says Weiner and is UNCONFIRMED -- settle it with the same retrieval that settles the rest. || CORRECTED 2026-09-18: THREE CORRECTIONS. (1) SafetyLit: this row says 503; the persisted artefact is exit 35, 0 bytes, no HTTP response. A 503 did occur, on a separate unpersisted WebFetch afterwards -- empty first, then 503. (2) SEVEN ROUTES overstates it: three of the seven are metadata APIs that cannot return full text (SafetyLit index, OpenAlex byline, Crossref deposit check), so the full-text attempts were four URLs on three hosts -- and the batch''s own priors named two routes never tried, an institutional repository copy and the authors'' own pages. (3) C10 KEEPS REFUSING THE RE-DETERMINATION is false: specifications holds 0 rows, so C10 passes having examined nothing and is listed under PASSED HAVING EXAMINED NOTHING. No re-determination was attempted this batch -- assess_cell.py was invoked only with --help. The cell is undetermined because nothing has been written, not because a gate refused it.', "updated_at" = '2026-09-18 22:44' WHERE "gap_id" = 'GAP-026';
UPDATE "gaps" SET "description" = 'GAP-018 PREDICTOR PASSED ITS FIRST PROSPECTIVE TEST, 19 AGAINST A PREDICTED FLOOR OF 8 -- AND ONE PASS IS NOT A RESULT. The predictor: a paper cites the literature of its OWN INDEPENDENT VARIABLE, so what an anchor MEASURES predicts its backward yield better than what it is ABOUT. Batch 17 pre-registered a falsifiable floor for REF-00979 (Chow et al., propulsion across a slope series) in two places committed before the pass -- the batch-16 deferral note and this batch priors file -- stating that fewer than 5 matches would WEAKEN the predictor. Measured: 19 of 30. REF-00980 (Sanford 1997) returned 5 of 25 against a prior of 0-2, low on count and exactly right on character. RUNNING TALLY, derive it rather than trusting this line: REF-00985 slope-series biomechanics 23/46, REF-00979 slope-series biomechanics 19/30, REF-00977 effects review 6/117, REF-00980 threshold test 5/25, REF-00984 instrument review 0/38. WHAT IS STILL OWED BEFORE THIS BECOMES DOCTRINE: GAP-018 asked for three or four prospective passes and this is ONE. The two remaining assigned deferrals that can test it are REF-00983 and REF-00986, both slope-adjacent biomechanics, so the predictor says both should yield -- record a floor for each BEFORE the pass. A WEAK INDEPENDENT CORROBORATION arrived unasked: REF-00979 and REF-00985 reference sets OVERLAP on the 1989 portable-ramp paper (10.3109/03790798909166390), which is what the predictor implies two same-variable anchors should do. Weak because two papers in one small literature will overlap anyway; recorded so it is not later mistaken for a second test. || CORRECTED 2026-09-18: SUPERSEDED BY GAP-029. This description asserts the GAP-018 predictor passed its first prospective test at 19 against a floor of 8. That 19 is a screen artefact -- the screen matched any propulsion paper -- and this row was closed by status only, leaving the retracted claim standing as the register''s text. Derive any yield: python3 scripts/research/mining_screen.py --all --compare.', "updated_at" = '2026-09-18 22:44' WHERE "gap_id" = 'GAP-027';
UPDATE "gaps" SET "description" = 'THE GAP-018 PREDICTOR IS FALSIFIED, AND THE RESULT REPORTED AS ITS FIRST SUCCESS WAS A SCREEN ARTEFACT. THIS RETRACTS A CLAIM MADE EARLIER IN THIS SAME BATCH. The predictor: a paper cites the literature of its OWN INDEPENDENT VARIABLE, so what an anchor MEASURES predicts backward yield better than what it is ABOUT. TWO PRE-REGISTERED PREDICTIONS, BOTH FAILED, IN OPPOSITE DIRECTIONS. REF-00983, whose independent variable IS ramp slope, predicted >= 8 and returned 2 of 23 -- its references are the TRANSIT-VEHICLE and ADA-guidelines literature, because a reference list follows the papers FIELD and problem framing, not its independent variable. REF-00986, whose independent variable is activity type, predicted <= 4 and returned 9 of 45. Both failing in opposite directions on one test is the hypothesis being wrong, not noise. THEN THE SCREEN WAS TESTED AND IT IS CONFOUNDED, which is worse. The screen regex carries propuls and accessib, so ANY wheelchair-propulsion paper matches regardless of slope content. Under a STRICT slope-only screen (ramp|slope|incline|gradient|grade|cross-slope): REF-00986 falls 9 to 0 of 45; REF-00979 falls 19 TO 2 OF 30. REF-00979 IS THE 19-OF-30 THIS BATCH REPORTED AS THE PREDICTORS FIRST PASSED PROSPECTIVE TEST, in a commit message, a session record and a PR body. It was counting cites wheelchair-propulsion papers, which is trivially true of a wheelchair-propulsion paper. NOTE WHICH ANCHOR SURVIVES THE STRICT SCREEN BEST: REF-00980, 4 of 25, the one I predicted LOW -- its hits are genuinely ramp-titled. So the strict screen inverts the original ranking as well. WHAT IS NOW OWED: (1) GAP-018 and GAP-027 are superseded by this row; do not cite either as support. (2) Every yield figure this project has recorded for a mining pass used the loose screen and is an OVERCOUNT of slope relevance -- re-derive with the strict screen before quoting any of them. (3) If a predictor is wanted at all, the candidate the data now suggests is FIELD AND PROBLEM FRAMING rather than independent variable, and it must be pre-registered and tested the same way rather than adopted because it fits five retrospective points. || CORRECTED 2026-09-18: THIS GAP''S OWN RANKING CLAIM IS WITHDRAWN. It states that the strict screen INVERTS the original ranking and that REF-00980 survives best. Neither holds. REF-00985 -- the anchor that founded GAP-018 -- was not re-derived when this was written, and it tops BOTH screens (strict 8 of 46, loose 23 of 46), so the top of the ranking is unmoved. What the strict screen does is reorder the MIDDLE: REF-00980 rises, REF-00979 falls, REF-00986 goes to zero. The retraction of the 19-of-30 pass STANDS and is unaffected; what is withdrawn is the claim about ranking, which was published under a second instrument that had not itself been validated. Both screens are now named and versioned in governance/mining-screens.yaml and every figure above is re-derivable: python3 scripts/research/mining_screen.py --all --compare. Item (2) of this gap -- re-derive every recorded yield under the strict screen -- is DISCHARGED by that command, which is why it was built rather than filed.', "updated_at" = '2026-09-18 22:44' WHERE "gap_id" = 'GAP-029';
UPDATE "gaps" SET "status" = 'CLOSED-FIXED', "description" = 'B06 KEEPS A CURATED gaps.status LIST THAT IS NARROWER THAN THE COLUMN OWN CHECK, AND I TRIPPED IT. The column CHECK permits anything LIKE OPEN% OR LIKE CLOSED%; test_db_integrity B06 enumerates a fixed tuple. Closing GAP-018 and GAP-027 as CLOSED-SUPERSEDED -- accurate, and accepted by the writer and the column -- turned a BLOCKING check red at 73/74. Resolved by using CLOSED-DECIDED, a ratified value that fits (both were closed by the decision recorded in GAP-029), rather than by widening B06, because adding a value to a check to accommodate a value I had just invented is the shape of disabling a test to get green. WHAT IS ACTUALLY OWED: B06 is a curated vocabulary sitting beside a column that declares its own, which is CLAUDE.md rule 8 (never curate a fact the machine can compute) in a test file. Either B06 derives from the column CHECK, or the column CHECK is tightened to the enumerated set and B06 reads it -- the present arrangement means a writer and a blocking check disagree about the vocabulary, and the disagreement is only discoverable by tripping it. Note CLOSED-SUPERSEDED is the semantically right value for a superseded gap and the project has no way to express it. || CORRECTED 2026-09-18: FIXED, and the premise needed correcting first. This says B06 keeps a list narrower than the column''s own CHECK -- true, but dbcore.check_values could not read that CHECK, because gaps.status declares a LIKE disjunction rather than an IN list and check_values parses only IN forms (its own docstring says a third form must be added there, not worked around at the call site). So: dbcore.check_expression now returns a column''s CHECK expression whatever its shape, and B06 asserts that expression instead of a curated tuple. Verified on a scratch copy -- CLOSED-SUPERSEDED, the accurate value this batch abandoned to get green, now passes.', "updated_at" = '2026-09-18 22:45' WHERE "gap_id" = 'GAP-032';

-- search_executions: 0 insert(s), 2 update(s)
UPDATE "search_executions" SET "findings_note" = 'THE PRIOR HELD AND GAP-016 IS NOT CLOSED. Seven routes, every one persisted as an artefact because a failed retrieval is retrieved evidence of a failed retrieval: academia.edu 403 (two different copies), researchgate 403, JSTOR 200 but the body is a bot interstitial not the article, SafetyLit 503 then an empty body, OpenAlex 429 (budget exhausted for this environment, resets midnight UTC). CROSSREF IS THE ONE INFORMATIVE NULL: a bibliographic title search returns five neighbouring papers and NOT this one, which VERIFIES rather than assumes the no-DOI fact the whole GAP-016 problem rests on -- JAPR never deposited it. CONSENSUS returned the record with the same abstract and the byline Alison G. Vredenburgh et al., corroborating existence and authorship-lead at index level, still not full text. CONSEQUENCE, STATED PLAINLY: extraction 45 stays skim/preliminary, REF-01002 stays UNVERIFIED, determination gate 1 stays open, C10 keeps refusing the re-determination, and parameter 3 x MOB stays undetermined. Nothing about the 7 percent figure moved and nothing should have. AN UNRESOLVED METADATA DISCREPANCY IS ALSO RECORDED: TRID prints the fourth author as Weiner, Jerome M; a web-search summary rendered it Welner, J. M. Neither is a retrieved authoritative index and this batch could not settle it -- the stored author row says Weiner and is flagged as unconfirmed. || CORRECTED 2026-09-18: CORRECTED TWICE OVER, and the second correction was also wrong. This note says SafetyLit returned 503 then an empty body. The persisted artefact e3b0c44298fc1c14.txt is status=null, exit=35, bytes=0 -- a connect failure with no HTTP response -- so the ORDER is reversed. The session record then retracted the 503 outright, which is also false: the harness transcript records a separate WebFetch of the same URL at 21:17:17 returning HTTP 503 Service Unavailable, AFTER the connect failure. Both events happened, empty first. The 503 leaves no artefact because that retrieval went through WebFetch instead of retrieval_log.fetch, which is how a claim about a retrieval came to rest on nothing a later reader could check. Also: this row says seven routes; ten attempts were made and three were unpersisted.' WHERE "exec_id" = 72;
UPDATE "search_executions" SET "findings_note" = 'PREDICTION MET, AND THIS IS THE PREDICTOR FIRST PROSPECTIVE TEST RATHER THAN A THIRD RETROSPECTIVE OBSERVATION. Predicted >= 8 of the references would match; 19 OF 30 DO. The prediction was written into the deferral note in batch 16 and into this batch priors file, both committed before the pass ran, so it is a test and not a description. GAP-018 asked for three or four such passes before the predictor is treated as doctrine; this is one, and it should be counted as one rather than as confirmation. WHAT THE SEAM CONTAINS: the propulsion-on-slopes literature almost in full -- kinetic analysis on indoor and outdoor surfaces, uphill handrim biomechanics, load on the upper extremity, EMG during paraplegic propulsion, and TWO 1989 portable-ramp papers (10.1177/030802268905201209 and 10.3109/03790798909166390, the latter already staged as candidate 101 in batch 16, which is a cross-confirmation that the two anchors reference sets overlap where the predictor says they should). DEPTH-1: nothing discovered here is mined in this pass. || CORRECTED 2026-09-18: RETRACTED. This note opens PREDICTION MET, 19 OF 30. The 19 is a SCREEN ARTEFACT: the screen carried ''propuls'' and ''accessib'', so any wheelchair-propulsion paper matched regardless of slope, and REF-00979 IS a propulsion paper. Derive it rather than quoting either figure: python3 scripts/research/mining_screen.py --ref REF-00979 --compare. GAP-029 carries the retraction; GAP-018 and GAP-027 are superseded. The prediction was neither met nor missed -- it was scored on an instrument that could not measure it.' WHERE "exec_id" = 73;

-- search_candidates: 0 insert(s), 3 update(s)
UPDATE "search_candidates" SET "exec_id" = 77, "notes" = '|| RESOLVED 2026-09-18 (R15, re-described from the source; admitted as REF-01003): Retrieved via Crossref. The staged description called it a second independent perceived-difficulty study on running slope AND cross slope, distance-conditioned -- that half holds. WHAT THE HYPOTHESIS GOT WRONG: it did not say the 23 participants WALKED at their preferred pace, so they are ambulatory people with vision or mobility limitations, NOT wheelchair users. Graded PROXY for MOB on that basis. Full byline is Longmuir, Freeland, Fitzgerald, Yamada and Axelson, not Longmuir alone as the Consensus record implied. T3 (clinical + lower_control): a pilot field study with no control condition, so it cannot lift parameter 3 off proxy.

REATTRIBUTED 2026-09-18 from exec 71 to exec 77 by session_2026-09-18-research-batch-17-vredenburgh-full-read-and-mining: Staged against exec 71, a Co-1 web search whose own findings_note reads ZERO YIELD with results_admitted=0. The search that surfaced it was the unlogged Consensus query, backfilled as exec 77, which search_admissions already records as admitting REF-01003. Migration data_20260918220811 asserted this correction had been made; it had not, because no verb could write exec_id. db.py reattribute-candidate is that verb. || RESOLVED 2026-09-18 (R15, re-described from the source; admitted as REF-01003): EDGE BACKFILLED. The resolution itself stands as written; what is added is the candidate-to-source link in a COLUMN. --admitted-ref-id was supplied at the original resolution and written only into this notes field, so nothing could join a candidate to the source it became. Migration 088 adds search_candidates.resolved_ref_id and integrity check S01 uses it to compare this candidate''s exec_id against the exec that actually admitted REF-01003 -- the comparison that would have caught the exec-71 mis-attribution when it was made.', "resolved_ref_id" = 'REF-01003' WHERE "candidate_id" = 107;
UPDATE "search_candidates" SET "exec_id" = 77, "notes" = '|| RESOLVED 2026-09-18 (R15, re-described from the source; admitted as REF-01004): Retrieved via Crossref. The staged description held: five slope levels (1:6, 1:8, 1:10, 1:12, 1:14) crossed with three rise heights (15, 30, 45 cm), with perceived discomfort alongside EMG and pulse. WHAT IT ADDS BEYOND THE HYPOTHESIS: the paper states 1:8 is recommendable when rise is LOW and installation space insufficient -- a second anchoring-tier stated value, pointing the opposite way from REF-01002 7 percent, and reconciling with it through conditions rather than contradicting (one conditions on distance, one on rise). Also reports no significant difference between 1:10 and 1:12. Published in HFES Proceedings 54(9):698-702; a Korean-language twin exists at 10.5143/jesk.2010.29.4.681 and is the same study in a second venue.

